'use strict';
const $=s=>document.querySelector(s),E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),L=window.THLaundryLabel,R=n=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(n||0);
const params=new URLSearchParams(location.hash.slice(1));let key=params.get('session'),role=['Customer','Operator','Owner'].includes(params.get('role'))?params.get('role'):'Customer',state,selected='',busy=false,refreshing=false,newForm=false;
if(!key){key=Array.from(crypto.getRandomValues(new Uint8Array(32)),x=>x.toString(16).padStart(2,'0')).join('');history.replaceState(null,'','#session='+key+'&role='+role);}
const customerURL=()=>location.origin+'/demo#session='+key+'&role=Customer';
function tell(text,error=false){$('#message').className='alert '+(error?'error':'success');$('#message').textContent=text;}
async function api(path,p){const r=await fetch('/api/laundry-demo/'+path,{method:p?'POST':'GET',cache:'no-store',credentials:'omit',signal:AbortSignal.timeout(20000),headers:{Authorization:'Bearer '+key,'Content-Type':'application/json','X-Top-Hills':'1'},body:p?JSON.stringify(p):undefined});const v=await r.json();if(!r.ok){const e=Error(v.error||'Belum tersimpan. Coba lagi.');e.status=r.status;throw e;}return v;}
async function send(action,extra={},as=role){if(busy)return;busy=true;document.querySelectorAll('button').forEach(b=>b.disabled=true);const payload={action,id:selected,role:as,revision:state.revision,mutationId:crypto.randomUUID(),...extra};try{let v;try{v=await api('action',payload);}catch(e){if(e.status||e.name==='AbortError')throw e;v=await api('action',payload);}state=v;if(action==='submit'){selected=state.orders.at(-1).id;newForm=false;}render();tell(action==='submit'?'Check-in tersimpan. Nomor order tampil di bawah; buka tab Operator untuk menerima.':'Perubahan tersimpan di ruang latihan.');}catch(e){tell(e.message,true);if(e.status===409)await reload(true);}finally{busy=false;document.querySelectorAll('button').forEach(b=>b.disabled=false);}}
async function reload(force=false){if(refreshing||busy&&!force)return;refreshing=true;try{const next=await api('state');if(force||next.revision!==state?.revision){state=next;render();}}catch(e){tell(e.message,true);}finally{refreshing=false}}
function changeRole(v){role=v;newForm=false;history.replaceState(null,'','#session='+key+'&role='+role);render();}
const control=(action,label,data={},as=role,description='')=>`<div class="demo-action"><div><strong>${E(label)}</strong>${description?`<p class="muted">${E(description)}</p>`:''}</div><button class="primary" data-act="${E(action)}" data-values="${E(JSON.stringify(data))}" data-role="${as}">Jalankan</button></div>`;
function customer(o){if(!o||newForm)return `<span class="eyebrow">01 / Customer check-in</span><h2>Hari yang ringan.<br>Laundry yang terurus.</h2><p class="muted">Coba mengirim order sendiri. Setelah tersimpan, ikuti perjalanan laundry dari sisi pelanggan dan petugas.</p><div class="card room"><div><small>Lokasi dari QR · tidak dapat diganti</small><b>A01 · Gedung A</b><p>Lantai 1 · Kamar kost fiktif</p></div><span class="tag">Terkunci</span></div><form id="customer-form" class="grid"><label>Nama contoh<input name="name" value="Nadia Contoh" minlength="2" maxlength="100" required autocomplete="off"></label><label>WhatsApp fiktif<input value="080000000000" readonly aria-describedby="fictional-contact"></label><small id="fictional-contact" class="full">Nomor ini hanya untuk latihan. Tidak ada pesan yang dikirim.</small><label>Hubungan dengan kamar<select name="relationship"><option>Penghuni</option><option>Tamu</option><option>Keluarga</option></select></label><label>Penyerahan barang<select name="method"><option value="pickup">Jemput di kamar</option><option value="dropoff">Antar ke counter</option></select></label><label class="full">Layanan awal<select name="serviceId">${state.services.map(s=>`<option value="${s.id}" ${s.id==='THL-regular-refresh'?'selected':''}>${E(s.name)} · ${R(s.price)} / ${E(s.unit)}</option>`).join('')}</select><small id="service-rule"></small></label><label class="full">Instruksi contoh<textarea name="note" maxlength="300" placeholder="Contoh: pisahkan pakaian putih."></textarea></label><p class="alert full">Harga final dikonfirmasi setelah timbang. Tidak ada pembayaran nyata di demo ini.</p><label class="check full"><input type="checkbox" required> Saya menggunakan data fiktif dan kamar sudah sesuai.</label><button class="primary full" type="submit">Kirim check-in demo →</button></form>`;
return `<span class="eyebrow">Check-in tercatat</span><h2>${E(o.customer.name)}, pesanan Anda masuk.</h2><p class="muted">Nomor order: <strong>${E(o.id)}</strong></p>${status(o)}<p>Diterima oleh <strong>${E(o.acceptedBy?.name||'belum ada petugas')}</strong>. Revisi R${o.customerRevision}, diterima R${o.acceptedRevision}.</p>${o.price?`<h2>${R(o.price.total)}</h2><p>${E(o.price.service.name)} · ${o.price.billedQuantity} ${E(o.price.service.unit)}</p>`:'<p class="alert">Menunggu barang diterima dan ditimbang oleh operator.</p>'}${o.price&&!o.priceApproved&&o.acceptedRevision===o.customerRevision?control('approve-price','Setujui harga final',{},'Customer','Persetujuan Anda membuka langkah pembayaran.'):''}${o.identity!=='CONFIRMED'?control('confirm-identity','Ini milik saya',{...o.customer},'Customer'):''}${!['COMPLETED','CANCELLED','CANCEL REQUESTED','RETURN REQUESTED'].includes(o.status)?'<button id="cancel-order" class="danger">Ajukan pembatalan</button>':''}<div class="row" style="margin-top:24px"><button data-role-switch="Operator">Lihat dari sisi Operator →</button><button id="another">Buat order contoh lain</button></div>`;}
function status(o){return `<div class="status-grid">${[['Laundry',o.status],['Identitas',o.identity],['Pembayaran',o.pay.status],['Setoran',o.set.status],['Refund',o.ref.status],['Hasil',o.clear]].map(([a,b])=>`<div><small>${a}</small><strong>${E(L(b))}</strong></div>`).join('')}</div>`;}
function staff(o){if(!o)return `<span class="eyebrow">Ruang kerja ${role}</span><h2>Antrean masih kosong.</h2><p class="muted">Pindai QR pada ponsel atau buka tab Pelanggan, lalu kirim check-in pertama Anda.</p><button class="primary" data-role-switch="Customer">Coba sebagai pelanggan →</button>`;
let actions='';if(role==='Operator'){
 if(o.status==='SUBMITTED'||o.acceptedRevision<o.customerRevision)actions+=control('accept','Terima order / revisi',{},role,'Nama Operator Contoh akan tercatat sebagai penerima.');
 if(['AWAITING PICKUP','AWAITING DROPOFF'].includes(o.status))actions+=control('receive','Terima 1 kantong & label',{proofId:'demo-photo',bags:1,location:'Rak demo A01'},role,'Bukti foto fiktif dipakai otomatis. Di meja asli, kamera langsung wajib.');
 if(['PICKED UP','RECEIVED AT COUNTER'].includes(o.status))actions+='<div class="demo-action"><div><strong>Timbang & harga final</strong><p class="muted">Coba berat atau jumlah sesuai layanan.</p></div><button class="primary" id="weigh">Isi hasil timbang</button></div>';
 if(o.price&&!o.priceApproved)actions+='<p class="alert">Menunggu persetujuan pelanggan. <button data-role-switch="Customer">Buka pelanggan</button></p>';
 if(o.priceApproved&&!['PENDING','PAID','OVERPAID'].includes(o.pay.status)&&!['CANCELLED','RETURN REQUESTED'].includes(o.status))actions+=control('create-pay','Buat PAY cash fiktif',{method:'Cash'});
 if(o.pay.status==='PENDING')actions+=control('verify-pay','Catat penerimaan cash fiktif',{amount:o.price.total-o.pay.received,proofId:'demo-upload',reference:'KUITANSI-DEMO'},role,'Tidak ada uang yang ditagih.');
 if(o.priceApproved&&o.status==='PRICE CONFIRMATION PENDING')actions+=control('process','Pindai label & mulai mesin',{batch:'MESIN-DEMO-01',scannedId:o.id},role,'Kode label cocok dengan THL ini.');
 if(o.status==='IN PROCESS')actions+=control('ready','Catat foto QC · siap serah',{proofId:'demo-photo'});
 if(o.status==='READY FOR HANDOVER')actions+=control('handover','Serahkan ke pelanggan',{proofId:'demo-photo',recipient:o.customer.name});
 if(o.set.status==='IN TRANSIT')actions+=control('submit-set','Ajukan setoran cash fiktif',{proofId:'demo-upload',actual:o.set.gross,fee:0,account:'REKENING-FIKTIF',reference:'SETORAN-DEMO'},role,'Owner harus memeriksa secara terpisah.');
 if(o.status==='RETURN REQUESTED')actions+=control('return','Kembalikan barang',{proofId:'demo-photo',recipient:o.customer.name});
 if(o.status==='CANCEL REQUESTED'&&!o.requiresOwner)actions+=control('approve-cancel','Setujui pembatalan',{reason:'Permintaan pelanggan contoh'});
 if(o.status==='ON HOLD')actions+=control('resume','Lanjutkan tahap yang tertahan',{reason:'Kendala latihan sudah selesai'});
}else{
 if(o.set.status==='PENDING VERIFICATION')actions+=control('approve-set','Cocokkan setoran sebagai Owner',{},'Owner','Pemeriksa berbeda dari penerima cash dan pengaju setoran.');
 if(o.status==='CANCEL REQUESTED')actions+=control('approve-cancel','Putuskan pembatalan',{reason:'Pembatalan contoh disetujui'},'Owner');
 if(o.ref.status==='REQUESTED')actions+=control('refund-approve','Setujui refund fiktif',{reason:'Refund latihan disetujui'},'Owner');
 if(o.ref.status==='APPROVED')actions+=control('refund-pay','Catat refund sebagai Finance Contoh',{proofId:'demo-upload',amount:o.ref.amount,reference:'REF-DEMO'},'Finance','Peran Finance hanya disimulasikan di ruang latihan.');
 if(o.ref.status==='REFUNDED'&&o.ref.settlementAdjustment?.status!=='MATCHED')actions+=control('refund-reconcile','Cocokkan dana refund sebagai Owner',{proofId:'demo-upload',reference:'REKON-DEMO',cashReturned:o.set.status!=='MATCHED'&&o.pay.method==='Cash'?o.ref.paid:0,reason:'Dana kembali dan mutasi contoh cocok'},'Owner');
 if(o.clear==='CLEAR'||o.clear==='CANCELLED CLEAR')actions='<p class="alert success">Selesai. Barang, pembayaran, dan rekonsiliasi pada skenario ini sudah cocok.</p>';
 if(!actions)actions='<p class="alert">Belum ada persetujuan Owner yang menunggu. Operator melanjutkan pekerjaan dan mengajukan setoran.</p>';
}
return `<span class="eyebrow">${role==='Owner'?'Kontrol & rekonsiliasi':'Pekerjaan berikutnya'}</span><h2>${E(o.id)}</h2><p>${E(o.customer.name)} · Gedung A / A01 / Lantai 1 · ${o.customer.method==='pickup'?'Jemput kamar':'Antar counter'}</p>${status(o)}<div class="balance-strip"><span class="tag">Harga ${R(o.price?.total)}</span><span class="tag">Diterima ${R(o.pay.received)}</span></div>${o.alerts.map(a=>`<p class="alert">${E(a)}</p>`).join('')}<div>${actions||'<p class="muted">Tahap sudah lengkap. Lanjutkan pemeriksaan Owner.</p>'}</div><div class="row" style="margin-top:20px"><button data-role-switch="${role==='Owner'?'Operator':'Owner'}">Lihat dari sisi ${role==='Owner'?'Operator':'Owner'} →</button></div>`;}
function render(){if(!state)return;if(!selected&&state.orders.length)selected=state.orders.at(-1).id;const o=state.orders.find(x=>x.id===selected);$('#view').innerHTML=`<div class="demo-hero"><div><span class="eyebrow">Top Hills, dari scan sampai selesai</span><h1>Coba satu perjalanan laundry.</h1><p class="muted">Pelanggan mengirim. Operator mengerjakan. Owner mencocokkan.</p></div><div class="sync">Tersimpan bersama · ruang demo</div></div><div class="demo-nav" role="tablist" aria-label="Peran latihan">${[['Customer','01 · Pelanggan'],['Operator','02 · Operator'],['Owner','03 · Owner']].map(([r,t])=>`<button role="tab" aria-selected="${role===r}" data-role-switch="${r}">${t}</button>`).join('')}</div><div class="demo-layout"><section class="card" role="tabpanel" aria-label="Latihan ${role}">${role==='Customer'?customer(o):staff(o)}</section><aside class="demo-side"><div class="card demo-qr-card"><span class="eyebrow">Coba dari ponsel</span><h3>Scan sebagai pelanggan</h3><canvas id="demo-qr" aria-label="QR membuka ruang latihan ini sebagai pelanggan"></canvas><p>QR ini membuka kamar A01 fiktif. Buka tautan yang sama di laptop untuk berperan sebagai operator atau owner.</p><div class="row"><button id="copy-link">Salin tautan</button><button id="download">Unduh QR</button></div></div><div class="card"><h3>Order ruang ini <span class="tag">${state.orders.length}/10</span></h3><ul class="demo-list">${state.orders.map(x=>`<li><button data-order="${E(x.id)}">${E(x.customer.name)} · #${E(x.id.split('-').at(-1))}</button><small>${E(L(x.status))}</small></li>`).join('')||'<li class="muted">Belum ada check-in.</li>'}</ul><p><small>Berakhir ${new Date(state.expiresAt).toLocaleDateString('id-ID',{timeZone:'Asia/Jakarta'})}</small></p><button id="new-room">Buat ruang latihan baru</button></div></aside></div><details class="card"><summary>Jejak aktivitas demo · ${state.events.length} kejadian</summary><ol class="timeline">${state.events.map(x=>`<li><strong>${E(x.actor)} · ${E(x.action)}</strong><small>${E(x.orderId)} · ${new Date(x.at).toLocaleString('id-ID',{timeZone:'Asia/Jakarta'})}</small>${E(L(x.status))}</li>`).join('')||'<p>Jejak muncul setelah check-in pertama.</p>'}</ol></details><p class="release-note">Ingin mencoba kondisi lain? <a href="/sop-demo.html">Jalankan skenario SOP</a> atau <a href="/sop-coverage">lihat cakupan dan batas versi ini</a>. QRIS, WhatsApp, kamera nyata, dan login staf tidak diuji oleh ruang latihan ini.</p>`;
makeRoomQR($('#demo-qr'),customerURL());$('#demo-qr').style.width='230px';document.querySelectorAll('[data-role-switch]').forEach(b=>b.onclick=()=>changeRole(b.dataset.roleSwitch));document.querySelectorAll('[data-order]').forEach(b=>b.onclick=()=>{selected=b.dataset.order;newForm=false;render()});document.querySelectorAll('[data-act]').forEach(b=>b.onclick=()=>send(b.dataset.act,JSON.parse(b.dataset.values),b.dataset.role));$('#copy-link').onclick=()=>navigator.clipboard.writeText(customerURL()).then(()=>tell('Tautan ruang latihan disalin.')).catch(()=>tell('Salin alamat halaman dari browser Anda.',true));$('#download').onclick=()=>{const a=document.createElement('a');a.href=$('#demo-qr').toDataURL();a.download='Top-Hills-QR-Demo.png';a.click()};$('#new-room').onclick=()=>{location.href='/demo';};$('#another')?.addEventListener('click',()=>{newForm=true;render()});$('#cancel-order')?.addEventListener('click',()=>{const reason=prompt('Alasan pembatalan contoh:','Customer berubah rencana');if(reason)send('cancel',{reason},'Customer')});$('#weigh')?.addEventListener('click',weighForm);
if($('#customer-form')){$('#customer-form').onsubmit=e=>{e.preventDefault();send('submit',Object.fromEntries(new FormData(e.target)),'Customer')};const update=()=>{const service=state.services.find(s=>s.id===$('[name=serviceId]').value);$('#service-rule').textContent=THServices.duration(service)+' · '+THServices.rule(service)};$('[name=serviceId]').onchange=update;update();}}
function weighForm(){const o=state.orders.find(x=>x.id===selected);$('#modal').innerHTML=`<h2>Timbang laundry contoh</h2><p>${E(state.services.find(s=>s.id===o.customer.serviceId).name)}</p><form id="weigh-form" class="grid"><label>Berat (kg)<input name="weight" type="number" step="0.01" min="0" max="1000" required value="2"></label><label>Jumlah barang / lembar<input name="quantity" type="number" step="1" min="0" max="1000" required value="2"></label><p class="muted full">Gunakan berat untuk layanan kiloan/load, jumlah untuk layanan satuan. Aturan minimum diperiksa saat menyimpan.</p><div class="row full"><button class="primary">Simpan harga</button><button type="button" id="close-modal">Batal</button></div></form>`;$('#modal').showModal();$('#close-modal').onclick=()=>$('#modal').close();$('#weigh-form').onsubmit=async e=>{e.preventDefault();const p=Object.fromEntries(new FormData(e.target));$('#modal').close();await send('weigh',{...p,proofId:'demo-photo'},'Operator');};}
(async()=>{try{state=await api('start',{});render();}catch(e){$('#view').innerHTML='<h1>Ruang belum dapat dibuka.</h1><p>'+E(e.message)+'</p><a class="button primary" href="/demo">Buat ruang latihan baru</a>';}})();
setInterval(()=>{if(!document.hidden&&!busy&&!$('#modal').open&&!document.activeElement?.matches('input,textarea,select'))reload();},8000);window.addEventListener('online',()=>reload(true));window.addEventListener('offline',()=>tell('Koneksi terputus. Tunggu online sebelum menyimpan.',true));
